export type MetaParams = { UUID: string; GroupingIdentifier: string; WFControlFlowMode: 0 | 1 | 2; CustomOutputName: string };

export type ActionId = keyof typeof ACTIONS;
export type ActionKey = keyof typeof actions;
/** Parameter keys declared for an action, plus the keys every action accepts. */
export type ParamKey<I extends string> = I extends ActionId ? (typeof ACTIONS)[I]["params"][number] | "UUID" | "GroupingIdentifier" | "WFControlFlowMode" | "CustomOutputName" : string;
